def settle(charges, slots):
    total = sum(charges.values())
    if total == 0:
        return {identifier: 0 for identifier in charges}
    allocations = {}
    remainders = {}
    for identifier, weight in charges.items():
        allocations[identifier], remainders[identifier] = divmod(slots * weight, total)
    remaining = slots - sum(allocations.values())
    for identifier in sorted(charges, key=lambda identifier: (-remainders[identifier], identifier))[:remaining]:
        allocations[identifier] += 1
    return allocations

charges = {'zebra': 7, 'gale': 5, 'fern': 5, 'iris': 0, 'alder': 5}
original = charges.copy()
result = settle(charges, 7)
assert result == {'zebra': 2, 'gale': 1, 'fern': 2, 'iris': 0, 'alder': 2}
assert charges == original
edge = {'z': 1, 'a': 1}
assert settle(edge, 1) == {'z': 0, 'a': 1}
assert settle({}, 4) == {}
assert settle({'a': 0, 'b': 0}, 9) == {'a': 0, 'b': 0}
assert settle({'b': 1, 'a': 1}, 2**54 + 1) == {'b': 2**53, 'a': 2**53 + 1}
assert settle(dict(reversed(list(charges.items()))), 7) == result
print({'result': result, 'edge_expected': settle(edge, 1), 'checks': 'passed'})

